<?php
namespace App\Services;
use App\Models\{AttendanceParticipant,Empleado,EmployeeTrainingCredential,TrainingEvaluationAttempt,TrainingRequirement}; use Illuminate\Support\Collection;
class TrainingRequirementResolverService
{
 public function requirementsFor(Empleado$employee):Collection{return TrainingRequirement::forCompany($employee->company_id)->where('is_active',true)->where('required',true)->where(function($q)use($employee){$q->where('requirement_type','company')->orWhere(fn($x)=>$x->where('requirement_type','job')->where('requirement_reference',$employee->cargo))->orWhere(fn($x)=>$x->where('requirement_type','area')->where('requirement_reference',$employee->area_departamento))->orWhere(fn($x)=>$x->where('requirement_type','employee')->where('requirement_reference',(string)$employee->id));})->with('topic')->get()->unique('training_topic_id')->values();}
 public function routeFor(Empleado$employee):Collection{return$this->requirementsFor($employee)->map(function($requirement)use($employee){$credential=EmployeeTrainingCredential::where('company_id',$employee->company_id)->where('employee_id',$employee->id)->where('training_topic_id',$requirement->training_topic_id)->where('status','valid')->latest('issued_at')->first();$passed=TrainingEvaluationAttempt::where('employee_id',$employee->id)->where('result','passed')->whereHas('evaluation',fn($q)=>$q->where('training_topic_id',$requirement->training_topic_id))->latest('submitted_at')->first();$attendance=AttendanceParticipant::where('employee_id',$employee->id)->whereHas('record',fn($q)=>$q->where('status','confirmed'))->whereHas('event',fn($q)=>$q->where('company_id',$employee->company_id)->where('attendable_type','training_session')->whereHasMorph('attendable',[\App\Models\TrainingSession::class],fn($s)=>$s->where('training_topic_id',$requirement->training_topic_id)->where('status','closed')))->latest('created_at')->first();$completed=$attendance&&(!$requirement->requires_evaluation||$passed)&&(!$requirement->requires_certificate||$credential);$baseDate=$credential?->issued_at??$passed?->submitted_at??$attendance?->created_at;$expires=$credential?->expires_at;if(!$expires&&$completed&&$requirement->validity_months&&$baseDate)$expires=$baseDate->copy()->addMonthsNoOverflow($requirement->validity_months);$status=!$completed?'pending':($expires&&$expires->isPast()?'expired':($expires&&$expires->lte(now()->addDays(30))?'expiring':'completed'));return compact('requirement','status','credential','passed','attendance','expires');});}
}
